133	/** Express middleware: requires a valid Clerk session */
134	export function requireAuth(req: Request, res: Response, next: NextFunction): void {
135	  if (isAgentBypass(req)) { applyBypassToReq(req); next(); return; }
136	  const { userId } = getAuth(req);
137	  if (!userId) {
138	    res.status(401).json({ error: "Unauthorized" });
139	    return;
140	  }
141	  next();
142	}
