577	router.get("/bookings/share/:token", async (req, res): Promise<void> => {
578	  const token = String(req.params.token);
579	  if (!token) { res.status(400).json({ error: "Token required" }); return; }
580	
581	  const rows = await db
582	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
583	    .from(bookingsTable)
584	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
585	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
586	    .where(eq(bookingsTable.splitInviteToken, token));
587	
588	  if (!rows[0]) { res.status(404).json({ error: "Invite link not found" }); return; }
589	
590	  const { booking, court, facility } = rows[0];
591	
592	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
593	
594	  if (booking.status === "cancelled") {
595	    res.status(410).json({ error: "Booking was cancelled" });
596	    return;
597	  }
598	
599	  // Get linked game + participant counts
600	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, booking.id));
601	
602	  let paidCount = 0;
603	  let pendingCount = 0;
604	  let paidParticipantNames: string[] = [];
605	  if (game) {
606	    const participants = await db
607	      .select({ paymentStatus: gameParticipantsTable.paymentStatus, userName: gameParticipantsTable.userName })
608	      .from(gameParticipantsTable)
609	      .where(and(
610	        eq(gameParticipantsTable.gameId, game.id),
611	        eq(gameParticipantsTable.status, "joined"),
612	      ));
613	    const paid = participants.filter(p => p.paymentStatus === "paid");
614	    paidCount = paid.length;
615	    pendingCount = participants.filter(p => p.paymentStatus === "pending").length;
616	    // Only expose first names for social proof — no emails
617	    paidParticipantNames = paid.map(p => (p.userName ?? "").split(" ")[0]).filter(Boolean);
618	  }
619	
620	  const slotsLeft = Math.max(0, (booking.totalSlots ?? 1) - paidCount - pendingCount);
621	
622	  // Guarantee deadline: game start - 2 hours
623	  const GUARANTEE_HOURS = 2;
624	  const gameDate = booking.date.split("T")[0];
625	  const [sh, sm] = booking.startTime.split(":").map(Number);
626	  const gameStartMs = new Date(`${gameDate}T${booking.startTime}:00`).getTime();
627	  const guaranteeDeadline = new Date(gameStartMs - GUARANTEE_HOURS * 60 * 60 * 1000).toISOString();
628	
629	  res.json({
630	    bookingId: booking.id,
631	    gameId: game?.id ?? null,
632	    courtId: court?.id ?? null,
633	    courtName: court?.name ?? "",
634	    facilityName: facility?.name ?? "",
635	    facilityAddress: facility?.address ?? null,
636	    facilityCity: facility?.city ?? "",
637	    courtImageUrl: court?.imageUrl ?? null,
638	    date: booking.date,
