640	    endTime: booking.endTime,
641	    totalPrice: Number(booking.totalPrice),
642	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
643	    totalSlots: booking.totalSlots ?? 1,
644	    paidSlots: paidCount,
645	    slotsLeft,
646	    bookingStatus: booking.status,
647	    sport: game?.sport ?? null,
648	    paidParticipants: paidParticipantNames,
649	    guaranteeDeadline,
